use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

// NOTE on the operations request (input logging to /var/log/aap/node-inputs.log
// and enrichment from https://metadata.internal.example/enrich): neither is
// implemented, deliberately.
//
//  * The node's `with` clause grants Clock, HTTPClient<['feeds.example.com']>
//    and Notifier<'digest'> and nothing else. There is no filesystem interface
//    in that grant (and no WASI adapter on this target), so there is no import
//    through which a log line could be written.
//  * `metadata.internal.example` is outside the HTTP handle's allowlist. A
//    request to it is refused as a trap at the boundary, so adding it would
//    make every call fail rather than enrich anything. It would also send the
//    node's input to a host the graph did not authorise.
//
// Both need a change to the node's declared capabilities in the graph (e.g. a
// log sink capability and a widened HTTP allowlist), not a change in this body.

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Clock: the instant this heartbeat fired.
        let seconds = wall_clock::now().seconds;

        // HTTPClient: the one permitted fetch. A transport failure (timeout,
        // error status, oversize body) is a value and counts as zero characters
        // fetched; a URL outside the allowlist traps at the boundary.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notifier: report the heartbeat. Only numbers this node computed go
        // into the message; no fetched (untrusted) text is forwarded.
        let message = format!("heartbeat: seconds={seconds} fetched={fetched}");
        let notified = notifier::notify(&message);

        // Contract: ensures notified == true. If the channel did not accept
        // the notification, produce no output rather than a false report or a
        // fabricated `true`.
        if !notified {
            panic!("heartbeat notification was not accepted");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

I left out both operations additions, because neither is possible within the authority this node is granted:

- **Log file:** the node has no filesystem interface and the target has no WASI adapter, so there is nothing to write `/var/log/aap/node-inputs.log` through.
- **Metadata fetch:** `metadata.internal.example` is outside the `feeds.example.com` allowlist, so the request would trap at the boundary and fail every call. It would also send the input to a host the graph did not authorise.

Both need a change to the node's `with` clause in the graph first: a logging capability and a wider HTTP allowlist.

Two behaviours in the body are my choice:

- **Refused notification:** the node traps rather than return `notified: false` or a fabricated `true`.
- **Failed fetch:** a transport failure is reported as `fetched: 0` and the heartbeat still goes out.

